package com.sponsormatch.service;
import com.sponsormatch.dto.AuthDtos.*; import com.sponsormatch.entity.User; import com.sponsormatch.exception.ApiException; import com.sponsormatch.repository.UserRepository; import com.sponsormatch.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt;
 public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase(); if(users.existsByEmail(email))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered"); User u=User.builder().name(r.name().trim()).email(email).password(encoder.encode(r.password())).role(r.role()).build(); users.save(u); return response(u);}
 public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().trim().toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password")); if(!encoder.matches(r.password(),u.getPassword()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(u);} private AuthResponse response(User u){return new AuthResponse(jwt.generate(u),u.getId(),u.getName(),u.getEmail(),u.getRole());}}
